tape( 'when `k` is sufficiently negative, the function copies nothing', function test( t ) {
	var expected;
	var out;
	var A;
	var B;

	A = [ 1.0, 2.0, 3.0, 4.0 ];
	B = [ 9.0, 9.0, 9.0, 9.0 ];

	out = gtril( 2, 2, -2, A, 2, 1, 0, B, 2, 1, 0 );

	expected = [ 9.0, 9.0, 9.0, 9.0 ];
	t.deepEqual( out, expected, 'returns expected value' );
	t.end();
});

