tape( 'the function leaves `B` unchanged when `M` or `N` is equal to zero', function test( t ) {
	var expected;
	var out;
	var A;
	var B;

	A = [ 1.0, 2.0, 3.0, 4.0 ];
	expected = [ 9.0, 9.0, 9.0, 9.0 ];

	B = [ 9.0, 9.0, 9.0, 9.0 ];
	out = gtril( 0, 2, 0, A, 2, 1, 0, B, 2, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	B = [ 9.0, 9.0, 9.0, 9.0 ];
	out = gtril( 2, 0, 0, A, 2, 1, 0, B, 2, 1, 0 );
	t.deepEqual( out, expected, 'returns expected value' );

	t.end();
});

tape( 'the function leaves `B` unchanged when `M` or `N` is equal to zero (accessors)', function test( t ) {
	var expected;
	var A;
	var B;

	A = [ 1.0, 2.0, 3.0, 4.0 ];
	expected = [ 9.0, 9.0, 9.0, 9.0 ];

	B = [ 9.0, 9.0, 9.0, 9.0 ];
	gtril( 0, 2, 0, toAccessorArray( A ), 2, 1, 0, toAccessorArray( B ), 2, 1, 0 );
	t.deepEqual( B, expected, 'returns expected value' );

	B = [ 9.0, 9.0, 9.0, 9.0 ];
	gtril( 2, 0, 0, toAccessorArray( A ), 2, 1, 0, toAccessorArray( B ), 2, 1, 0 );
	t.deepEqual( B, expected, 'returns expected value' );

	t.end();
});
